<!DOCTYPE html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Accueil des modules — Ambassadors</title><link rel="icon" href="{{ asset('images/logo.png') }}">
<style>
:root{--navy:#020b2f;--gold:#e8b52f;--muted:#afbee6}*{box-sizing:border-box}html,body{min-height:100%}body{margin:0;overflow-x:hidden;background:radial-gradient(circle at 50% 20%,#123c91 0,#06194e 35%,var(--navy) 75%);color:#fff;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.portal{position:relative;min-height:100vh;overflow:hidden;padding:22px 28px 30px}.portal:before{position:absolute;inset:0;content:"";pointer-events:none;opacity:.12;background-image:linear-gradient(#fff 1px,transparent 1px),linear-gradient(90deg,#fff 1px,transparent 1px);background-size:48px 48px;mask-image:linear-gradient(to bottom,#000,transparent 82%)}.topbar{position:relative;z-index:20;display:flex;align-items:center;justify-content:space-between;gap:20px;width:min(1480px,100%);margin:auto}.brand{display:flex;align-items:center;gap:13px;color:#fff;text-decoration:none}.brand img{width:68px;height:68px;object-fit:contain;filter:drop-shadow(0 5px 12px #0007)}.brand strong,.brand span,.user__name strong,.user__name small{display:block}.brand strong{font-size:18px;letter-spacing:.05em}.brand span{color:var(--gold);font-size:12px;font-weight:800;letter-spacing:.08em}.user{display:flex;align-items:center;gap:12px}.user__name{text-align:right}.user__name small{color:#b8c5e0}.logout{display:grid;place-items:center;width:42px;height:42px;border:1px solid #ffffff2b;border-radius:50%;background:#ffffff12;color:#fff;cursor:pointer;font-size:18px}.intro{position:relative;z-index:2;margin:10px auto 0;text-align:center}.intro__eyebrow{margin:0 0 6px;color:var(--gold);font-size:12px;font-weight:900;letter-spacing:.2em;text-transform:uppercase}.intro h1{margin:0;font-family:Georgia,serif;font-size:clamp(2rem,4vw,3.5rem);line-height:1.05}.intro p{margin:9px auto 0;color:#c7d3ec;font-size:15px}.coverflow{position:relative;z-index:3;width:min(1500px,100%);margin:0 auto;user-select:none}.viewport{position:relative;height:560px;outline:none;perspective:1100px;touch-action:pan-y;cursor:grab}.viewport:active{cursor:grabbing}.stage{position:absolute;inset:0;transform-style:preserve-3d}.card{--a:#1260e6;--b:#031847;position:absolute;top:50%;left:50%;display:block;width:320px;height:420px;overflow:hidden;border:1px solid #ffffff52;border-radius:24px;background:linear-gradient(155deg,var(--a),var(--b));box-shadow:0 28px 65px #0009;transform-style:preserve-3d;transition:transform .62s cubic-bezier(.2,.75,.18,1),opacity .42s,filter .42s;will-change:transform;cursor:pointer;text-decoration:none;color:#fff}.card--violet{--a:#7544c7;--b:#160c45}.card--cyan{--a:#0a8db1;--b:#03233f}.card--amber{--a:#d88b19;--b:#422007}.card--indigo{--a:#405ad6;--b:#111d55}.card--emerald{--a:#159b78;--b:#05372e}.card--rose{--a:#d8466a;--b:#481025}.card--fuchsia{--a:#a840b6;--b:#35103e}.card--slate{--a:#486a96;--b:#10223e}.card:not(.is-active){filter:saturate(.78) brightness(.76)}.card.is-active{border-color:#ffd56f;box-shadow:0 34px 90px #000b,0 0 0 2px #f4b62980,0 0 45px #0d66ff75}.campus{position:absolute;inset:0;background:linear-gradient(to bottom,transparent 14%,var(--b) 92%),url('{{ asset('images/campus.jpg') }}') center/cover;opacity:.3;mix-blend-mode:luminosity}.glow{position:absolute;top:-70px;right:-70px;width:220px;height:220px;border-radius:50%;background:#ffffff20}.status{position:absolute;top:20px;right:18px;padding:7px 11px;border:1px solid #ffffff30;border-radius:999px;background:#06173c88;font-size:10px;font-weight:800;backdrop-filter:blur(8px)}.status:before{display:inline-block;width:7px;height:7px;margin-right:6px;border-radius:50%;background:#6cf0a5;box-shadow:0 0 10px #6cf0a5;content:""}.icon{position:absolute;top:72px;left:50%;display:grid;place-items:center;width:82px;height:82px;border:1px solid #ffffff4d;border-radius:22px;background:#ffffff1f;transform:translateX(-50%);backdrop-filter:blur(9px)}.icon svg{width:46px;height:46px}.copy{position:absolute;right:23px;bottom:24px;left:23px}.index{color:var(--gold);font-size:11px;font-weight:900;letter-spacing:.2em}.copy strong{display:block;margin-top:8px;font-family:Georgia,serif;font-size:25px;line-height:1.08}.copy p{min-height:58px;margin:10px 0 15px;color:#e0e6f5;font-size:12px;line-height:1.5}.action{display:flex;align-items:center;justify-content:space-between;padding-top:13px;border-top:1px solid #ffffff30;color:#ffd164;font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.07em}.control{position:absolute;z-index:150;top:50%;display:grid;place-items:center;width:48px;height:48px;border:1px solid #ffffff30;border-radius:50%;background:#06143fd6;color:#fff;font-size:24px;cursor:pointer;transform:translateY(-50%);backdrop-filter:blur(10px)}.control:hover{border-color:var(--gold);background:#0b3c9d}.left{left:16px}.right{right:16px}.caption{min-height:68px;margin-top:-34px;text-align:center}.caption strong{display:block;color:var(--gold);font-family:Georgia,serif;font-size:24px}.caption span{display:block;max-width:560px;margin:7px auto 0;color:var(--muted);font-size:13px}.dots{display:flex;justify-content:center;gap:8px;margin-top:10px}.dot{width:8px;height:8px;padding:0;border:0;border-radius:50%;background:#ffffff45;cursor:pointer;transition:.3s}.dot.is-active{width:30px;border-radius:999px;background:var(--gold)}.hint{margin:12px 0 0;color:#8597bd;text-align:center;font-size:11px}.empty{max-width:650px;margin:100px auto;padding:40px;border:1px solid #ffffff22;border-radius:24px;background:#ffffff0c;text-align:center}@media(max-width:900px){.portal{padding:16px}.user__name{display:none}.viewport{height:520px}.card{width:280px;height:390px}.left{left:0}.right{right:0}.caption{margin-top:-18px}}@media(max-width:560px){.brand img{width:52px;height:52px}.brand strong{font-size:14px}.brand span{font-size:9px}.intro h1{font-size:2rem}.intro p{font-size:13px}.viewport{height:480px}.card{width:min(76vw,270px);height:375px}.copy strong{font-size:21px}.control{top:auto;bottom:8px;width:42px;height:42px}.left{left:calc(50% - 56px)}.right{right:calc(50% - 56px)}.caption{margin-top:0}.hint{display:none}}@media(prefers-reduced-motion:reduce){.card,.dot{transition:none}.hint{display:none}}
</style></head><body><main class="portal">
<header class="topbar"><a class="brand" href="{{ route('home') }}"><img src="{{ asset('images/logo.png') }}" alt="Logo Ambassadors"><span><strong>AMBASSADORS</strong>EDUCATIONAL COMPLEX</span></a><div class="user"><div class="user__name"><strong>{{ auth()->user()->name }}</strong><small>Choisissez votre espace</small></div><form method="POST" action="{{ route('filament.admin.auth.logout') }}">@csrf<button class="logout" type="submit" title="Se déconnecter" aria-label="Se déconnecter">↪</button></form></div></header>
<section class="intro" aria-labelledby="portal-title"><p class="intro__eyebrow">Foi · Vision · Discipline</p><h1 id="portal-title">Bienvenue dans votre espace</h1><p>Choisissez le module dans lequel vous souhaitez travailler.</p></section>
@if(count($modules))<section class="coverflow" id="module-carousel" aria-label="Choix du module"><div class="viewport" tabindex="0" role="region" aria-roledescription="carrousel"><div class="stage">
@foreach($modules as $index => $module)<a class="card card--{{ $module['color'] }}" href="{{ $module['url'] }}" data-index="{{ $index }}" role="group" aria-roledescription="diapositive" aria-label="{{ $index + 1 }} sur {{ count($modules) }} : {{ $module['name'] }}"><span class="campus"></span><span class="glow"></span><span class="status">{{ $module['active'] ? 'Disponible' : 'En préparation' }}</span><span class="icon"><x-filament::icon :icon="$module['icon']" /></span><span class="copy"><span class="index">{{ str_pad((string)($index+1),2,'0',STR_PAD_LEFT) }}</span><strong>{{ $module['name'] }}</strong><p>{{ $module['description'] }}</p><span class="action">Ouvrir le module <b>→</b></span></span></a>@endforeach
</div><button class="control left" type="button" aria-label="Module précédent">‹</button><button class="control right" type="button" aria-label="Module suivant">›</button></div><div class="caption" aria-live="polite"><strong></strong><span></span></div><nav class="dots" aria-label="Sélectionner un module">@foreach($modules as $index => $module)<button class="dot" type="button" data-index="{{ $index }}" aria-label="Afficher {{ $module['name'] }}"></button>@endforeach</nav><p class="hint">Navigation manuelle · Glissez les cartes ou utilisez les boutons et les flèches du clavier</p></section>
@else<section class="empty"><h2>Aucun module disponible</h2><p>Votre compte ne possède encore aucun accès actif. Contactez l’administration.</p></section>@endif
</main>
@if(count($modules))<script>
(()=>{const root=document.querySelector('#module-carousel'),viewport=root.querySelector('.viewport'),cards=[...root.querySelectorAll('.card')],dots=[...root.querySelectorAll('.dot')],title=root.querySelector('.caption strong'),text=root.querySelector('.caption span');let active=0,dragStart=null;const offsetFor=index=>{let value=index-active;if(value>cards.length/2)value-=cards.length;if(value<-cards.length/2)value+=cards.length;return value};const render=()=>{const mobile=innerWidth<560;cards.forEach((card,index)=>{const offset=offsetFor(index),distance=Math.abs(offset),step=mobile?145:245,tilt=Math.min(68,43*Math.pow(distance,.58))*Math.sign(offset);card.style.transform=`translate3d(calc(-50% + ${step*offset}px),-50%,${-115*Math.pow(distance,.58)}px) rotateY(${-tilt}deg)`;card.style.opacity=Math.max(.08,1-distance*.16);card.style.zIndex=100-Math.round(distance);card.classList.toggle('is-active',index===active);card.setAttribute('aria-current',index===active?'true':'false')});dots.forEach((dot,index)=>dot.classList.toggle('is-active',index===active));title.textContent=cards[active].querySelector('.copy strong').textContent;text.textContent=cards[active].querySelector('.copy p').textContent};const go=index=>{active=(index+cards.length)%cards.length;render()};cards.forEach((card,index)=>card.addEventListener('click',event=>{if(index!==active){event.preventDefault();go(index)}}));dots.forEach((dot,index)=>dot.addEventListener('click',()=>go(index)));root.querySelector('.left').addEventListener('click',()=>go(active-1));root.querySelector('.right').addEventListener('click',()=>go(active+1));viewport.addEventListener('keydown',event=>{if(event.key==='ArrowLeft'){event.preventDefault();go(active-1)}if(event.key==='ArrowRight'){event.preventDefault();go(active+1)}});viewport.addEventListener('pointerdown',event=>dragStart=event.clientX);viewport.addEventListener('pointerup',event=>{if(dragStart===null)return;const delta=event.clientX-dragStart;if(Math.abs(delta)>40)go(active+(delta<0?1:-1));dragStart=null});viewport.addEventListener('pointercancel',()=>dragStart=null);addEventListener('resize',render,{passive:true});render()})();
</script>@endif</body></html>
